    <style>
        :root {
            --bg-color: #ffffff;
            --sidebar-bg: #f9fafb;
            --text-primary: #111827;
            --text-secondary: #6b7280;
            --border-color: #e5e7eb;
            --accent-color: #2563eb; /* Blue for active state */
            --hover-bg: #f3f4f6;
            --key-bg: #f3f4f6;
            --key-border: #d1d5db;
            --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: var(--font-family);
            background-color: #000; /* Outer background to simulate window frame */
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            color: var(--text-primary);
        }

        /* App Window Container */
        .app-window {
            width: 1200px;
            height: 800px;
            background-color: var(--bg-color);
            border-radius: 8px;
            box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
            overflow: hidden;
            display: flex;
            flex-direction: column;
            position: relative;
        }

        /* --- Header / Title Bar --- */
        .title-bar {
            height: 40px;
            background-color: #fff;
            border-bottom: 1px solid var(--border-color);
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 10px;
            font-size: 13px;
            color: var(--text-primary);
            flex-shrink: 0;
        }

        .title-bar-left {
            display: flex;
            align-items: center;
            gap: 15px;
        }

        .app-icon {
            width: 16px;
            height: 16px;
            border: 1px solid #ccc;
            display: inline-block;
        }

        .nav-arrows {
            display: flex;
            gap: 12px;
            color: var(--text-secondary);
        }

        .nav-arrow { cursor: pointer; font-size: 10px; }

        .menu-bar {
            display: flex;
            gap: 18px;
            margin-left: 10px;
        }

        .menu-item { cursor: pointer; padding: 2px 4px; }
        .menu-item:hover { background-color: var(--hover-bg); }

        .window-controls {
            display: flex;
            gap: 8px;
        }

        .control-btn {
            width: 28px;
            height: 28px;
            border-radius: 4px;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            color: var(--text-secondary);
        }
        .control-btn:hover { background-color: var(--hover-bg); }

        /* --- Main Layout --- */
        .main-container {
            display: flex;
            flex: 1;
            overflow: hidden;
        }

        /* Sidebar */
        .sidebar {
            width: 260px;
            background-color: var(--sidebar-bg);
            border-right: 1px solid var(--border-color);
            display: flex;
            flex-direction: column;
            padding: 16px;
            overflow-y: auto;
            flex-shrink: 0;
        }

        .back-link {
            display: flex;
            align-items: center;
            gap: 8px;
            color: var(--text-primary);
            text-decoration: none;
            font-size: 14px;
            margin-bottom: 16px;
            cursor: pointer;
        }

        .search-settings {
            position: relative;
            margin-bottom: 24px;
        }

        .search-input {
            width: 100%;
            padding: 8px 10px 8px 32px;
            border: 1px solid var(--border-color);
            border-radius: 6px;
            font-size: 14px;
            outline: none;
            background: white;
        }

        .search-icon {
            position: absolute;
            left: 10px;
            top: 50%;
            transform: translateY(-50%);
            color: #9ca3af;
            font-size: 14px;
        }

        .nav-group-title {
