            margin-top: 16px;
            margin-bottom: 8px;
            padding-left: 8px;
        }

        .nav-list {
            list-style: none;
        }

        .nav-item {
            display: flex;
            align-items: center;
            gap: 10px;
            padding: 8px 8px;
            border-radius: 6px;
            cursor: pointer;
            font-size: 14px;
            color: var(--text-primary);
            margin-bottom: 2px;
        }

        .nav-item:hover {
            background-color: #e5e7eb;
        }

        .nav-item.active {
            background-color: #e5e7eb; /* Slightly darker than sidebar bg as per screenshot */
            font-weight: 500;
        }

        .nav-icon {
            width: 16px;
            text-align: center;
            font-size: 14px;
        }

        /* Content Area */
        .content-area {
            flex: 1;
            padding: 40px 60px;
            overflow-y: auto;
            background-color: #fff;
            position: relative;
        }

        h1 {
            font-size: 24px;
            font-weight: 600;
            margin-bottom: 24px;
            color: var(--text-primary);
        }

        .content-search-row {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 24px;
        }

        .content-search {
            position: relative;
            flex: 1;
            max-width: 600px;
            margin-right: 20px;
        }

        .content-search input {
            width: 100%;
            padding: 10px 10px 10px 36px;
            border: 1px solid var(--border-color);
            border-radius: 6px;
            font-size: 14px;
        }

        .content-search .search-icon {
            left: 12px;
        }

        .keys-badge {
            background-color: #f3f4f6;
            color: #374151;
            padding: 6px 12px;
            border-radius: 6px;
            font-size: 13px;
            font-weight: 500;
            border: 1px solid transparent;
        }

        /* Shortcut List */
        .shortcut-list {
            border: 1px solid var(--border-color);
            border-radius: 8px;
            overflow: hidden;
        }

        .shortcut-row {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 16px 20px;
            border-bottom: 1px solid var(--border-color);
            transition: background-color 0.1s;
        }

        .shortcut-row:last-child {
            border-bottom: none;
        }

        .shortcut-row:hover {
            background-color: #fafafa;
            cursor: pointer;
        }

        .shortcut-info h3 {
            font-size: 14px;
            font-weight: 500;
            color: var(--text-primary);
            margin-bottom: 4px;
        }

        .shortcut-info p {
            font-size: 13px;
            color: var(--text-secondary);
        }

        .shortcut-keys {
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .key {
            background-color: var(--key-bg);
            border: 1px solid var(--key-border);
            border-radius: 4px;
            padding: 2px 6px;
            font-size: 12px;
            font-family: monospace;
            color: #374151;
            min-width: 24px;
            text-align: center;
            box-shadow: 0 1px 0 rgba(0,0,0,0.05);
        }

        .edit-icon {
            color: #9ca3af;
            font-size: 14px;
            margin-left: 8px;
            opacity: 0;
            transition: opacity 0.2s;
        }

        .shortcut-row:hover .edit-icon {
            opacity: 1;
            color: #6b7280;
        }

        /* Toast Notification */
        .toast-notification {
            position: absolute;
            bottom: 30px;
            left: 50%;
            transform: translateX(-50%);
            background-color: white;
            border: 1px solid var(--border-color);
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
            padding: 12px 24px;
            border-radius: 8px;
            display: flex;
            align-items: center;
            gap: 24px;
            font-size: 14px;
            z-index: 100;
        }

        .toast-dismiss {
            color: var(--text-primary);
            cursor: pointer;
            font-weight: 500;
        }
    </style>
</head>
